    assert candidates,(key,ch)
    units.append(dict(id='root5-review-'+key,status=status,compared_evidence_record_ids=candidates,locators=locators,finding=finding,limitation='Only the named propositions and bounded source readings are reviewed. Listed chapter evidence provides navigation; it does not certify every dependent assertion, boon field or another print witness.'))
